import unittest
from hourglass.timesheet import timesheet_lines
from hourglass.models import Shift, Span

def _shift(worker, minutes):
    return Shift(worker, "mon", Span(0, minutes))

class TimesheetLineTests(unittest.TestCase):
    def test_busiest_first_with_hours(self):
        shifts = [
            _shift("Odell", 390),
            _shift("Brisa", 240),
            _shift("Brisa", 300)
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Brisa: 2 shifts, 9.0 hours",
                "Odell: 1 shift, 6.5 hours"
            ]
        )

    def test_ranks_by_hours_not_shift_count(self):
        shifts = [
            _shift("Ann", 60),
            _shift("Ann", 60),
            _shift("Ann", 60),
            _shift("Zed", 240)
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Zed: 1 shift, 4.0 hours",
                "Ann: 3 shifts, 3.0 hours"
            ]
        )

    def test_rounds_quarter_hours_half_up(self):
        self.assertEqual(
            timesheet_lines([_shift("Quill", 75)]),
            ["Quill: 1 shift, 1.3 hours"]
        )

    def test_ties_sorted_by_name(self):
        shifts = [_shift("Zed", 60), _shift("Ann", 60)]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Ann: 1 shift, 1.0 hours",
                "Zed: 1 shift, 1.0 hours"
            ]
        )

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker_raises(self):
        for name in ("", "   "):
            shifts = [_shift("Brisa", 60), _shift(name, 60)]
            with self.assertRaises(ValueError):
                timesheet_lines(shifts)
